        &fixture.root,
        "public.app",
        WorkspaceAnalysisTargetKind::Declaration,
        "public.point",
        WorkspaceContextOptions::default(),
    )
    .unwrap();

    let impact_options = WorkspaceImpactOptions::default();
    let impact = workspace_analysis::impact(
        &fixture.root,
        "public.app",
        WorkspaceAnalysisTargetKind::Declaration,
        "public.work",
        impact_options,
