            "capability",
            "audit.write",
            "--max-nodes",
            "64",
            "--max-bytes",
            "1048576",
            "--depth",
            "3",
        ],
        &custom_impact,
    );

    let review = workspace_analysis::review(
        &fixture.root,
        "public.app",
        WorkspaceAnalysisTargetKind::Declaration,
        "public.work",
    )
    .unwrap();
    assert!(!review.ends_with('\n'));
